Let $\mathcal{P}$ be an integer interval partition of $\{1, \ldots, n\}$ into $K_{\cal P}$ intervals, i.e.
	\begin{align*}
		\mathcal{P} = \big\{\{1, \ldots, i_1-1\}, \{i_1, \ldots, i_2-1\}, \ldots, \{i_{K_{\mathcal{P}}-1}, \\
		\ldots, i_{K_{\mathcal{P}}} - 1\}\big\},
	\end{align*}
	for some integers $1 < i_1 < \cdots < i_{K_{\mathcal{P}}} = n + 1$, where $K_{\mathcal{P}} \geq 1$.

To specialize the dynamic programming algorithm to the  high-dimensional linear regression model of interest  by setting the loss function to be
\eqref{eq-wide-p} with
	\begin{equation} \mathcal L(I) = \sum_{t \in I}(y_t - x_t^{\top} \widehat \beta^\lambda_I)^2,
	\end{equation}
	where
	\begin{align}
		\widehat \beta^\lambda_I = arg\,min_{v \in \mathbb R^p} \bigg\{\sum_{t \in I} (y_t - x_t^{\top}v)^2  \nonumber \\
		+ \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \| v\|_1\bigg\}, \end{align}
	and $\lambda \geq 0$ is a tuning parameter.

\begin{algorithmic}
	\INPUT Data $\{(x_t, y_t)\}_{t=1}^{n}$, $\{\widetilde{\eta}_k\}_{k = 1}^{\widetilde{K}}$ ,  $\zeta > 0$.
	\State $(\widetilde{\eta}_0, \widetilde{\eta}_{\widetilde{K} + 1}) \leftarrow (0, n)$
	\For{$k = 1, \ldots, \widetilde{K}$}  
		\State $(s_k, e_k) \leftarrow (2\widetilde{\eta}_{k-1}/3 + \widetilde{\eta}_{k}/3, \widetilde{\eta}_{k}/3 + 2\widetilde{\eta}_{k+1}/3)$
		\State 
		\begin{align}
			& \left(\widehat{\beta}_1, \widehat{\beta}_2, \widehat{\eta}_k\right) \leftarrow arg\,min_{\substack{\eta \in \{s_k + 1, \ldots, e_k - 1\} \\ \beta_1, \beta_2 \in \mathbb{R}^{p},\, \beta_1 \neq \beta_2}}   \Bigg\{\sum_{t = s_k + 1}^{\eta}\bigl\|y_{t} - \beta_1^{\top} x_t\bigr\|^2_2 \nonumber \\
			& \hspace{0.5cm}+ \sum_{t = \eta + 1}^{e_k}\bigl\|y_t - \beta_2 x_t\bigr\|_2^2 \nonumber \\
		    & \hspace{0.5cm} + \zeta  \sum_{i = 1}^p \sqrt{(\eta - s_k)(\beta_1)_{i}^2 + (e_k - \eta)(\beta_2)_{i}^2}\Bigg\} \end{align}
	\EndFor
	\OUTPUT $\{\widehat{\eta}_k\}_{k = 1}^{\widetilde{K}}$.
\caption{Local Refinement. } \end{algorithmic}

\For{$k = 1, \ldots, \widetilde{K}$}  
		\State $(s_k, e_k) \leftarrow (2\widetilde{\eta}_{k-1}/3 + \widetilde{\eta}_{k}/3, \widetilde{\eta}_{k}/3 + 2\widetilde{\eta}_{k+1}/3)$
		\State 
		\begin{align}
			& \left(\widehat{\beta}_1, \widehat{\beta}_2, \widehat{\eta}_k\right) \leftarrow arg\,min_{\substack{\eta \in \{s_k + 1, \ldots, e_k - 1\} \\ \beta_1, \beta_2 \in \mathbb{R}^{p},\, \beta_1 \neq \beta_2}}   \Bigg\{\sum_{t = s_k + 1}^{\eta}\bigl\|y_{t} - \beta_1^{\top} x_t\bigr\|^2_2 \nonumber \\
			& \hspace{0.5cm}+ \sum_{t = \eta + 1}^{e_k}\bigl\|y_t - \beta_2 x_t\bigr\|_2^2 \nonumber \\
		    & \hspace{0.5cm} + \zeta  \sum_{i = 1}^p \sqrt{(\eta - s_k)(\beta_1)_{i}^2 + (e_k - \eta)(\beta_2)_{i}^2}\Bigg\} \end{align}

\begin{align}
			& \left(\widehat{\beta}_1, \widehat{\beta}_2, \widehat{\eta}_k\right) \leftarrow arg\,min_{\substack{\eta \in \{s_k + 1, \ldots, e_k - 1\} \\ \beta_1, \beta_2 \in \mathbb{R}^{p},\, \beta_1 \neq \beta_2}}   \Bigg\{\sum_{t = s_k + 1}^{\eta}\bigl\|y_{t} - \beta_1^{\top} x_t\bigr\|^2_2 \nonumber \\
			& \hspace{0.5cm}+ \sum_{t = \eta + 1}^{e_k}\bigl\|y_t - \beta_2 x_t\bigr\|_2^2 \nonumber \\
		    & \hspace{0.5cm} + \zeta  \sum_{i = 1}^p \sqrt{(\eta - s_k)(\beta_1)_{i}^2 + (e_k - \eta)(\beta_2)_{i}^2}\Bigg\} \end{align}

