The above result implies that, with probability tending to 1 as $n$ grows,
	\begin{align*}
		\max_{k = 1, \ldots, K}\frac{|\hat{\eta}_k - \eta_k|}{\Delta} \leq \frac{KC_{\epsilon} d^2_0 \sigma^2_{\epsilon}\log(n \vee p)}{\kappa^2 \Delta} \\
		\leq \frac{C_{\epsilon}}{C_{\mathrm{SNR}}\log^{\xi}(n \vee p)} \to 0,
	\end{align*}
	where in the second inequality we have used \Cref{assume:high dim coefficient}(\textbf{c}).  Thus, the localization error converges to zero in probability.

In particular, if we use the outputs of \eqref{eq-wide-p}, \eqref{eq-loss-1}, and \eqref{eq-beta-1} as the inputs of \Cref{algorithm:LR}, then it follows from \eqref{eq-lm-thm-1} and \eqref{eq:snr} that, for any $k \in \{1, \ldots, K\}$, 
	\begin{align*}
		s_k - \eta_{k - 1} > \frac{2}{3}\widetilde{\eta}_{k - 1} + \frac{1}{3}\widetilde{\eta}_{k} - \widetilde{\eta}_{k - 1} - \epsilon \\
		= \frac{1}{3}(\widetilde{\eta}_k - \widetilde{\eta}_{k-1}) - \epsilon > \Delta/3 - 5\epsilon/3 > 0
	\end{align*}
	and
	\begin{align*}
		s_k - \eta_{k} < \frac{2}{3}\widetilde{\eta}_{k - 1} + \frac{1}{3}\widetilde{\eta}_{k} - \widetilde{\eta}_{k} + \epsilon \\
		= - \frac{2}{3}(\widetilde{\eta}_{k-1} - \widetilde{\eta}_{k}) + \epsilon < -2\Delta/3 + 5\epsilon/3 < 0.
	\end{align*}

Next we apply the restricted eigenvalue conditions along with standard arguments from the Lasso literature to establish that 
			\begin{align}
				& \sum_{t \in I_1} \{x_t^{\top} (\widehat{\beta}^{\lambda}_I - \beta^*_{I_1})\}^2 + \sum_{t \in I_2} \{x_t^{\top} (\widehat{\beta}^{\lambda}_I - \beta^*_{I_2})\}^2 \nonumber \\
				& \hspace{2cm} \geq c_x^2 |I_1| \|\widehat{\beta}^{\lambda}_I - \beta^*_{I_1}\|^2 + c_x^2 |I_2| \|\widehat{\beta}^{\lambda}_I - \beta^*_{I_2}\|^2 \geq c_x^2 \kappa^2 \epsilon, \end{align}
			where $\epsilon$ is an upper bound on the localization error.

Note that
	\begin{equation} \|\widehat{\beta}^{\lambda}_I\|_1 \geq \|\beta^*_I(S)\|_1 - \|v(S)\|_1 + \|\widehat{\beta}^{\lambda}_I(S^c)\|_1
	\end{equation}
	and 
	\begin{equation} \|v\|_1 = \|v(S)\|_1 + \|\widehat{\beta}^{\lambda}_I(S^c)\|_1.
	\end{equation}

For \Cref{assume:change point regression model}, under \Cref{assume:high dim coefficient}(\textbf{a}) and (\textbf{c}), if there exists no true change point in $I = (s, e]$, and
	\[
		\lambda \geq \lambda_1 : = C_{\lambda}\sigma_{\varepsilon} \sqrt{\log(n \vee p)},
	\]
	where $C_{\lambda} > 0$ being an absolute constant, it holds that if $|I| \geq 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then
	\begin{align*}
		& \mathbb{P}\left\{\left|\sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\}\right| \leq \lambda^2 d_0 \right\} \\
		& \hspace{2cm}\geq 	1 - c_1 (n \vee p)^{-288^2C_x^2d_0c_2/c_x^2} - 2(n \vee p)^{-c_3};
	\end{align*}
	if $|I| < 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then 
	\begin{align*}
		\mathbb{P}\left\{\left|\sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\}\right| \leq C_4 \lambda \sqrt{\log(n \vee p)} d_0^{3/2}\right\} \geq 1 - 2(n \vee p)^{-c_3},
	\end{align*}
	where $C_4 > 0$ is an absolute constant depending on all the other constants.

To ease notation, in this proof, let $\widehat{\beta} = \widehat{\beta}^\lambda_{I}$ and $\beta^* = \beta^*_I$. 

\vskip 3mm
\noindent \textbf{Case 1.}  If $|I| \geq 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then $|I| > \log(n \vee p)$.  With probability at least $1 - c_1 \exp(-c_2 |I|) - 2(n \vee p)^{-c_3}$, we have that
	\begin{align*}
		& \sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\} \leq \lambda \sqrt{|I|} \|\beta^*\|_1 - \lambda \sqrt{|I|} \|\widehat{\beta}\|_1\leq \lambda \sqrt{|I|} \|\widehat{\beta} - \beta^*\|_1 \leq C_3 \lambda^2 d_0,
	\end{align*}
	where the fist inequality follows from the definition of $\widehat{\beta}$ and the second is due to \Cref{lemma:lasso}.

\vskip 3mm
\noindent \textbf{Case 2.}  If $|I| < 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then
	\begin{align*}
		\sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\}	 & \leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}\|\beta^*\|_1 \leq C_4 \lambda \sqrt{\log(n \vee p)} d_0^{3/2},
	\end{align*}
	since $\|\beta^*\|_1 \leq C_{\beta}d_0$.  In addition, it holds with probability at least $1 - 2(n \vee p)^{-c_3}$ that
	\begin{align*}
		 & \sum_{t \in I} \bigl\{(y_t - x_t^{\top}\beta^*)^2 - (y_t - x_t^{\top}\widehat{\beta})^2\bigr\} = - \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + 2\sum_{t \in I} \varepsilon_t x_t^{\top}(\widehat{\beta} - \beta^*) \\
		 \leq & - \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + \sum_{t \in I} \varepsilon_t^2 \leq \sum_{t \in I} \varepsilon_t^2   \\
		 \leq & \max\{\sqrt{|I|\log(n \vee p)}, \, \log(n \vee p)\} \leq C_4 \lambda \sqrt{\log(n \vee p)} d_0^{3/2},
	\end{align*}
	where the first inequality follow from $2ab \leq a^2 + b^2$ and letting $a = \varepsilon_t$, $b = x_t^{\top}(\widehat{\beta} - \beta^*)$,  the third inequality follows from the sub-Gaussianity of $\{\varepsilon_t\}$.

\textbf{Case 1.}  If $|I| \geq 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then $|I| > \log(n \vee p)$.  With probability at least $1 - c_1 \exp(-c_2 |I|) - 2(n \vee p)^{-c_3}$, we have that
	\begin{align*}
		& \sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\} \leq \lambda \sqrt{|I|} \|\beta^*\|_1 - \lambda \sqrt{|I|} \|\widehat{\beta}\|_1\leq \lambda \sqrt{|I|} \|\widehat{\beta} - \beta^*\|_1 \leq C_3 \lambda^2 d_0,
	\end{align*}
	where the fist inequality follows from the definition of $\widehat{\beta}$ and the second is due to \Cref{lemma:lasso}.

\textbf{Case 2.}  If $|I| < 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, then
	\begin{align*}
		\sum_{t \in I} \bigl\{(y_t - x_t^{\top}\widehat{\beta})^2 - (y_t - x_t^{\top}\beta^*)^2\bigr\}	 & \leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}\|\beta^*\|_1 \leq C_4 \lambda \sqrt{\log(n \vee p)} d_0^{3/2},
	\end{align*}
	since $\|\beta^*\|_1 \leq C_{\beta}d_0$.  In addition, it holds with probability at least $1 - 2(n \vee p)^{-c_3}$ that
	\begin{align*}
		 & \sum_{t \in I} \bigl\{(y_t - x_t^{\top}\beta^*)^2 - (y_t - x_t^{\top}\widehat{\beta})^2\bigr\} = - \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + 2\sum_{t \in I} \varepsilon_t x_t^{\top}(\widehat{\beta} - \beta^*) \\
		 \leq & - \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + \sum_{t \in I} (x_t^{\top} \beta^* - x_t^{\top} \widehat{\beta})^2 + \sum_{t \in I} \varepsilon_t^2 \leq \sum_{t \in I} \varepsilon_t^2   \\
		 \leq & \max\{\sqrt{|I|\log(n \vee p)}, \, \log(n \vee p)\} \leq C_4 \lambda \sqrt{\log(n \vee p)} d_0^{3/2},
	\end{align*}
	where the first inequality follow from $2ab \leq a^2 + b^2$ and letting $a = \varepsilon_t$, $b = x_t^{\top}(\widehat{\beta} - \beta^*)$,  the third inequality follows from the sub-Gaussianity of $\{\varepsilon_t\}$.

For \Cref{assume:change point regression model}, under \Cref{assume:high dim coefficient}(\textbf{a})-(\textbf{c}), for any interval $I = (s, e]$ and
	\[
		\lambda \geq \lambda_2 : = C_{\lambda}\sigma_{\varepsilon} \sqrt{d_0 \log(n \vee p)}, 
	\] 
	where $C_{\lambda} > 8C_{\beta}C_x/\sigma_{\varepsilon}$, it holds with probability at least of $1 - 2(n \vee p)^{-c}$ that,
	\begin{align*}	
		\| \widehat \beta^\lambda_{I} (S^c)\|_1 \le 3 \| \widehat \beta^\lambda_{I} (S )\|_1.
	\end{align*}

If in addition, the interval $I$ satisfies $|I| > 288^2 C^2_x d_0 \log(n \vee p)/c_x^2$, it holds with probability at least $1 - c_1 (n \vee p)^{-288^2C_x^2d_0c_2/c_x^2} - 2(n \vee p)^{-c_3}$ that
	\begin{align*}
		\left \|\widehat\beta_{I}^ \lambda - \frac{1}{|I|} \sum_{t \in I} \beta_t^* \right\|_2 \leq  \frac{C_5 \lambda \sqrt{d_0}}{\sqrt{|I|}} \quad \mbox{and} \quad \left \|  \widehat\beta_{I}^ \lambda - \frac{1}{|I|} \sum_{t \in I} \beta_t^* \right\|_1 \le  \frac{C_5 \lambda d_0}{\sqrt{|I|}},
	\end{align*}
	where $C_5 > 0$ is an absolute constant depending on other constants.

Denote $\widehat{\beta} = \widehat\beta_{I}^\lambda$ and $\beta^* = (|I|)^{-1}\sum_{t \in I} \beta^*_t$.  It follows from the definition of $\widehat{\beta}$ that 
	\[
		\sum_{t \in I} (y_t - x_t^{\top}\widehat{\beta})^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \leq \sum_{t \in I} (y_t - x_t^{\top}\beta^*)^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1,
	\]
	which leads to
	\begin{align*}
		\sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 +  2\sum_{t \in I}(y_t - x_t^{\top}\beta^*)x_t^{\top}(\beta^* - \widehat{\beta})  + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \\
		\leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1,
	\end{align*}
	therefore
	\begin{align}
		& \sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 + 2(\widehat{\beta} - \beta^*)^{\top}\sum_{t \in I} x_t x_t^{\top}(\beta^* - \beta^*_t) \nonumber \\
		& \hspace{3cm} \leq 2\sum_{t \in I} \varepsilon_t x_t^{\top}(\widehat{\beta} - \beta^*) + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}\bigl(\bigl\|\beta^*\bigr\|_1 - \bigl\|\widehat{\beta}\bigr\|_1\bigr). \end{align}

We bound	
	\[
		\left\|\sum_{t \in I} x_t x_t^\top (\beta^*  -\beta^*_t) \right\|_{\infty}.  
	\]
	For any $k \in \{1, \ldots, p\}$, the $k$th entry of $\sum_{t \in I} x_t x_t^\top (\beta^*  -\beta^*_t)$ satisfies that
	\begin{align*}
		& \mathbb{E}\left\{\sum_{t \in I} \sum_{j = 1}^p x_t(k)x_t(j)(\beta^*(j) - \beta^*_t(j))\right\} = \sum_{t \in I}\sum_{j = 1}^p \mathbb{E}\{x_t(k) x_t(j)\}\{\beta^*(j) - \beta^*_t(j)\} \\
		= & \sum_{j = 1}^p \mathbb{E}\{x_1(k) x_1(j)\} \sum_{t \in I}\{\beta^*(j) - \beta^*_t(j)\} = 0.
	\end{align*}

Note that $x_t^{\top}(\beta^* - \beta^*_t)$'s are sub-Gaussian random variables with a common parameter $2C_{\beta}C_x\sqrt{d_0}$, and $x_t$'s are sub-Gaussian random vectors with parameter $C_x$.  Therefore due to sub-Exponential inequalities \citep[e.g. Proposition~2.7.1 in][]{vershynin2018high}, it holds with probability at least of $1 - 2(n \vee p)^{-c}$ that,
	\begin{align}
		\left\|\sum_{t \in I} x_t x_t^\top (\beta^*  -\beta^*_t) \right\|_{\infty} \leq 2C_x C_{\beta}\sqrt{d_0}\max\{\sqrt{|I|\log(n \vee p)}, \, \log(n \vee p)\}\nonumber \\
		\leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}/4. \end{align}
	On the event $\mathcal{B}_I$, combining \eqref{eq-lem10-pf-2} and \eqref{eq-lem10-pf-1} yields
	\begin{align*}
		&\sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \\
		&\hspace{2cm}\leq \lambda/2 \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^* - \widehat{\beta}\bigr\|_1 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1. 
	\end{align*}
	The final claims follow from the same arguments as in \Cref{lemma:lasso}.

Denote $\widehat{\beta} = \widehat\beta_{I}^\lambda$ and $\beta^* = (|I|)^{-1}\sum_{t \in I} \beta^*_t$.  It follows from the definition of $\widehat{\beta}$ that 
	\[
		\sum_{t \in I} (y_t - x_t^{\top}\widehat{\beta})^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \leq \sum_{t \in I} (y_t - x_t^{\top}\beta^*)^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1,
	\]
	which leads to
	\begin{align*}
		\sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 +  2\sum_{t \in I}(y_t - x_t^{\top}\beta^*)x_t^{\top}(\beta^* - \widehat{\beta})  + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \\
		\leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1,
	\end{align*}
	therefore
	\begin{align}
		& \sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 + 2(\widehat{\beta} - \beta^*)^{\top}\sum_{t \in I} x_t x_t^{\top}(\beta^* - \beta^*_t) \nonumber \\
		& \hspace{3cm} \leq 2\sum_{t \in I} \varepsilon_t x_t^{\top}(\widehat{\beta} - \beta^*) + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}\bigl(\bigl\|\beta^*\bigr\|_1 - \bigl\|\widehat{\beta}\bigr\|_1\bigr). \end{align}

Note that $x_t^{\top}(\beta^* - \beta^*_t)$'s are sub-Gaussian random variables with a common parameter $2C_{\beta}C_x\sqrt{d_0}$, and $x_t$'s are sub-Gaussian random vectors with parameter $C_x$.  Therefore due to sub-Exponential inequalities \citep[e.g. Proposition~2.7.1 in][]{vershynin2018high}, it holds with probability at least of $1 - 2(n \vee p)^{-c}$ that,
	\begin{align}
		\left\|\sum_{t \in I} x_t x_t^\top (\beta^*  -\beta^*_t) \right\|_{\infty} \leq 2C_x C_{\beta}\sqrt{d_0}\max\{\sqrt{|I|\log(n \vee p)}, \, \log(n \vee p)\}\nonumber \\
		\leq \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}}/4. \end{align}

On the event $\mathcal{B}_I$, combining \eqref{eq-lem10-pf-2} and \eqref{eq-lem10-pf-1} yields
	\begin{align*}
		&\sum_{t \in I} \bigl\{x_t^{\top}(\widehat{\beta} - \beta^*)\bigr\}^2 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\widehat{\beta}\bigr\|_1 \\
		&\hspace{2cm}\leq \lambda/2 \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^* - \widehat{\beta}\bigr\|_1 + \lambda \sqrt{\max\{|I|, \, \log(n \vee p)\}} \bigl\|\beta^*\bigr\|_1. 
	\end{align*}

It follows from \Cref{lemma:RSS lasso} and \eqref{eq:one change point} that, with probability at least $1 - 2c_1 (n \vee p)^{-288^2C_x^2d_0c_2/c_x^2} - 2(n \vee p)^{-c_3}$ that, that
	\begin{align}
		& \sum_{t \in I_1}(y_t - x_t^{\top}\widehat{\beta}^\lambda_I)^2 + \sum_{t \in I_2}(y_t - x_t^{\top}\widehat{\beta}^\lambda_I)^2 = \sum_{ t\in I}(y_t - x_t^{\top}\widehat{\beta}^\lambda_I)^2  \nonumber \\
		\leq & \sum_{t \in I_1}(y_t - x_t^{\top}\widehat{\beta}^\lambda_{I_1})^2 + \sum_{t \in I_2}(y_t - x_t^{\top}\widehat{\beta}^\lambda_{I_2})^2 + \gamma \nonumber \\
		\leq & \sum_{t \in I_1}(y_t - x_t^{\top}\beta^*_{I_1})^2 + \sum_{t \in I_2}(y_t - x_t^{\top}\beta^*_{I_2})^2 + \gamma + 2C_3 \lambda^2 d_0. \end{align}

Moreover, we have
	\begin{align}
		& \sqrt{|I_1|} \|\Delta_1\|_2 + \sqrt{|I_2|} \|\Delta_2\|_2 \geq \sqrt{|I_1| \|\Delta_1\|_2^2 + |I_2| \|\Delta_2\|_2^2} \nonumber \\
		\geq & \sqrt{\inf_{v \in \mathbb{R}^p} \{|I_1| \|\beta^*_{\eta} - v\|^2 + |I_2| \|\beta^*_{\eta + 1} - v\|^2\}} = \kappa \sqrt{\frac{|I_1||I_2|}{|I|}} \geq \frac{\kappa}{\sqrt{2}}\min\{\sqrt{|I_1|}, \sqrt{|I_2|} \}. \end{align}

It follows from \Cref{lemma:RSS lasso} that the following holds with probability at least $1 - 3c_1 (n \vee p)^{-288^2C_x^2d_0c_2/c_x^2} - 2(n \vee p)^{-c_3}$ that,
	\begin{align}
		& \sum_{t\in I } (y_t -x_t^{\top} \widehat \beta^\lambda_ I )^2 \leq \sum_{t\in I_1 } (y_t -x_t^{\top} \widehat \beta^\lambda_ {I_1}  )^2 + \sum_{t\in I_2 } (y_t -x_t^{\top} \widehat \beta^\lambda_ {I_2}  )^2  + \sum_{t\in I_3} (y_t -x_t^{\top} \widehat \beta^\lambda_ {I_3}  )^2 + 2\gamma \nonumber \\
		\leq &  \sum_{t \in I_1 } (y_t -x_t^{\top}   \beta^* _ {I_1}  )^2 + \sum_{t \in I_2 } (y_t -x_t^{\top}   \beta^* _ {I_2}  )^2 + \sum_{t \in I_3 } (y_t -x_t^{\top}   \beta^* _ {I_3}  )^2 + 3C_3 \lambda^2 d_0 + 2\gamma,  \nonumber
	\end{align}
